namespace MmaManager.Core.Sim.Generation.Origins;

public static partial class OriginsChapters
{
    // ===================== ERA 6: THE GLOBAL GAME (2010-2023) =====================
    private static OriginsChapter[] Era6() => new[]
    {
        C("inhouse-streaming", 6, "A Channel of Your Own", 204, 276, A("prime-time-network-deal"),
            "The first promotion to launch its own subscription streaming service.",
            First("SignMedia:InHouseStream"),
            A("Media:InHouseStream"),
            A("A promotion can run its own streaming service: it airs everything, and the money is monthly subscriptions. A launch has a cost; a failed launch is a loss."),
            N("{Org} switches on its own channel",
              "No network, no carrier, no schedule: {Org} has built its own streaming service, and {Founder} presses the button at a launch party in {City}. For a monthly fee, fans anywhere can watch every card, every replay and every back-room documentary. The technology is supplied by {Partner}. The risk is entirely {Org}'s own. It is the first time a promotion has been its own broadcaster, and the first time it has been its own banker."),
            N("{Org} launches its own streaming service",
              "{Org} has launched a subscription streaming service, built with {Partner}, that shows every card on demand. Rival promoters are impressed and anxious. The service will cost millions to run; if it works, {Org} will no longer need a network to reach its fans. If not, the lesson will be expensive. The first month's subscriber count will be watched more closely than any title fight."),
            N("Every promotion a broadcaster",
              "{Year}. Broadband has reached enough homes that the arithmetic changes: a promotion can ship its own channel directly to a fan's screen, charge a monthly fee, and answer to nobody else. The first to try it, with the help of a platform company, finds the model is expensive and fragile. It is also freedom. Within a few seasons the larger promotions are all launching services of their own, and fans are learning to juggle subscriptions."),
            "A channel of your own: the first promotion launches its own streaming service."),

        C("scene-lagos-mumbai-santiago-gulf", 6, "A Second Wave of Scenes: Lagos, Mumbai, Santiago, Riyadh, Doha and Nairobi", 192, 270, A("scene-gulf-cape-andes"),
            "The first promotion to hold a card in one of these countries.",
            First("HoldEventInNewCountry"),
            A("CountryScene:NGA", "CountryScene:IND", "CountryScene:CHI", "CountryScene:KSA", "CountryScene:QAT", "CountryScene:KEN"),
            A("Scenes in Nigeria, India, Chile, Saudi Arabia, Qatar and Kenya wake; wrestling halls in Lagos and akhara gyms in India produce raw heavy talent."),
            N("{Org} lands in {City}",
              "{City}, {Country}, has been waiting for a promotion for a decade, and {Org} is the first to arrive. The hall is full, the television crews are local and the local fighters know exactly how good they are. {Founder} has a long list of gyms to visit and a short list of days to do it. A country of millions has joined the sport's audience in an evening."),
            N("{Org} is first into {City}",
              "{Org} has become the first promotion to run a show in {City}, {Country}. Local fighters have been training for years in the hope of exactly this. Rival promoters note that the talent pool of an entire country is now open to whoever moves first. The first card is sold out by Tuesday, and the second is already on the calendar. The mayor has promised a hall. Nobody in the room is pretending to be surprised."),
            N("Six more places join in",
              "{Year}. The talent has been there for years: Nigerian wrestlers in Lagos, Indian akhara champions, Chilean boxers, Kenyan distance runners with a taste for contact sport. Now six new scenes start in a few seasons, each with a flagship arena and a local star. The sport's map is nearly filled in, and the next generation of champions is as likely to come from one of these places as from the rooms where it all began."),
            "Scenes wake in Nigeria, India, Chile, Saudi Arabia, Qatar and Kenya."),

        C("global-pyramid-forms", 6, "The Pyramid", 216, 300, A("consolidation-wave"),
            "The world has promotions on every continent and a recognisable ladder from local shows to the international stage.",
            World("ContinentsWithPromotionsAtLeast", 5),
            A(),
            A("A pyramid of promotions: local shows feed regional ones, which feed national and international ones; fighters climb it and promotions know their rung."),
            null, null,
            N("A ladder from every town to the world stage",
              "{Year}. A boy in a small town who wants to be a fighter now knows exactly how: a local show on a Friday night, a regional promotion with a title, a national one with a television contract, an international one with a worldwide audience. Each rung has its own champions, its own sponsors and its own fighters on the way up or down. The sport that began in three rooms has a structure as clear as football's. The names have changed, but the ladder is the same."),
            "The pyramid forms: a clear ladder from local shows to the world stage.",
            "A world shift; no player variant."),

        C("major-streamer", 6, "A Streaming Giant Buys the Spectacle", 240, 324, A("inhouse-streaming"),
            "The first promotion to sign a global streaming service.",
            First("SignMedia:MajorStream"),
            A("Media:MajorStream"),
            A("Huge per-event licensing fees from a global streaming giant, which wants spectacles."),
            N("{Org} signs with {Partner}",
              "A streaming company with subscribers in a hundred countries has signed {Org} to a long-term deal, and {Founder} announces it from a stage in {City}. The fee is larger than any broadcaster has paid. The condition is plain: events, spectacle, stars. {Fighter} will headline the opening card. For the first time, a promotion can be seen in every country at the same moment, in any language, on any screen."),
            N("{Partner} signs {Org} for the world",
              "{Partner}, a streaming service with subscribers on every continent, has bought the rights to {Org}'s events. The amount is huge. The audience is the planet. Competing promotions, who built their own services at great expense, are reviewing their plans. A launch card is already pencilled in for the autumn, with a venue in {City} and a production crew twice the usual size. Executives at rival services say, off the record, that they were surprised by the number."),
            N("The whole world, one click away",
              "{Year}. A streaming company with a subscriber base measured in the hundreds of millions decides that fights are the sort of live event worth buying. The fee is a shock: bigger than anything the old broadcasters paid. The condition is that the events be spectacles. A promotion that can deliver them is, overnight, watched in homes on every continent. Others will follow the contract and the cheque."),
            "A streaming giant buys the spectacle: {Partner} signs a world deal."),

        C("scene-west-africa-maghreb-lima", 6, "The Last Corners: Accra, Casablanca, Dakar and Lima", 228, 320, A("scene-lagos-mumbai-santiago-gulf"),
            "The first promotion to hold a card in one of these countries.",
            First("HoldEventInNewCountry"),
            A("CountryScene:GHA", "CountryScene:MAR", "CountryScene:SEN", "CountryScene:PER"),
            A("Scenes in Ghana, Morocco, Senegal and Peru wake; traditional wrestling and boxing traditions feed local talent."),
            N("{Org} opens a scene in {City}",
              "{Org} has come to {City}, {Country}, and found that the local fighters had been waiting. The sport's tradition there is old: wrestling at festivals, boxing in the gyms, a crowd that knows what it is looking at. {Founder} says the first card was the easiest to promote in the company's history. The talent is real, the audience is eager and the rest of the world has not yet noticed."),
            N("{Org} is first into {City}",
              "{City}, {Country}, has its first card, thanks to {Org}. The venue was full and the home fighters were unforgettable. The map of the sport has nearly no white space left. Neighbouring countries are already sending scouts, and two broadcasters have rung the promoter's office to ask for the highlights. The home promotions will be watching the ticket sales with a mixture of envy and arithmetic. It is a very good week to be first."),
            N("The last corners fill in",
              "{Year}. Four more scenes join: the boxing gyms of Accra, the wrestling festivals of Dakar, the martial-arts halls of Casablanca and the street gyms of Lima. None of them are surprises to those who have watched local sport in those places for decades. They are new only to promoters. The talent is deep, the stories are fresh and every show is a first. There are few places left where a fighter could say that no one has ever promoted a card."),
            "Scenes wake in Ghana, Morocco, Senegal and Peru: the map is nearly full."),

        C("the-sport-you-built", 6, "The Sport You Built", 300, 372, A("global-pyramid-forms", "major-streamer", "global-brands-arrive", "scene-west-africa-maghreb-lima", "womens-headline-card", "weight-ladder-flyweight", "champion-vs-champion", "beer-and-energy-drinks",
                "first-backers", "rivals-appear", "scene-low-countries-canada", "lean-years", "specialists-fall", "japan-network-weekly"),
            "The world has reached the shape of today's game: every capability unlocked, scenes awake, a pyramid and a global audience.",
            new OriginsTrigger(OriginsTriggerKind.Dated, "Date"),
            A(),
            A("Origins mode converges: from here the world plays as today's mode does. The Story So Far shows a closing retrospective."),
            null, null,
            N("Thirty years",
              "{Year}. It began with eight men, one question and a legal pad. Now there are promotions on every continent, divisions from flyweight to heavyweight for men and women, referees, judges, doctors and a rulebook agreed by every commission. There are stars no one would have predicted and arenas no one would have believed. The fighters of the first night are retired, then remembered, then taught in gyms. The question Len Pastor wrote down is still being asked, in a thousand languages, every weekend. The answer is that it depends who is in the ring."),
            "Thirty years on: the sport you built stands where today's game begins.",
            "Closing chapter, narrated from the world's view; the engine may add a personal retrospective of the player's promotion."),
    };
}
